<section class="container page-section"><p class="breadcrumb"><a href="/">หน้าแรก</a> / สื่อและดาวน์โหลด</p><div class="page-heading"><p class="eyebrow">MEDIA LIBRARY</p><h1>สื่อและดาวน์โหลด</h1><p>ภาพ วิดีโอ และเอกสารประชาสัมพันธ์</p></div><nav class="tabs"><?php foreach(['album'=>'อัลบั้มภาพ','video'=>'วิดีโอ','document'=>'เอกสาร'] as $key=>$label): ?><a class="<?= $tab===$key?'selected':'' ?>" href="/media?tab=<?= $key ?>"><?= $label ?></a><?php endforeach ?></nav><form class="filters"><input type="hidden" name="tab" value="<?= e($tab) ?>"><label class="search-field"><span class="sr-only">ค้นหาสื่อ</span><?= icon('search',19) ?><input name="q" value="<?= e($_GET['q']??'') ?>" placeholder="ค้นหาสื่อ..."></label><button class="button">ค้นหา</button></form>
<?php if(!$items): require ROOT . '/views/partials/empty.php'; else: ?><div class="<?= $tab==='document'?'documents-list':'news-grid' ?>"><?php foreach($items as $card): if($tab==='album'): require ROOT . '/views/partials/card.php'; elseif($tab==='video'): ?><article class="news-card"><img class="video-cover" src="<?= e(image_url($card['cover_id']?(int)$card['cover_id']:null)) ?>" alt="<?= e($card['title']) ?>" loading="lazy"><div class="card-copy"><span class="badge">วิดีโอ</span><h2><?= e($card['title']) ?></h2><p><?= e($card['excerpt']) ?></p><?php if(safe_url($card['external_url'])): ?><a class="text-link" href="<?= e($card['external_url']) ?>" target="_blank" rel="noopener noreferrer">ชมวิดีโอที่เว็บไซต์ต้นทาง ↗</a><?php else: ?><p class="muted">ลิงก์วิดีโอรอยืนยัน</p><?php endif ?></div></article><?php else: $documentFiles=all('SELECT m.* FROM content_media cm JOIN media m ON m.id=cm.media_id WHERE cm.content_id=? AND m.mime=? ORDER BY cm.sort_order',[$card['id'],'application/pdf']); ?><article class="document-card"><h2><?= e($card['title']) ?></h2><p><?= e($card['excerpt']) ?></p><?php foreach($documentFiles as $file): ?><div class="file-row"><?= icon('news',25) ?><span><strong><?= e($file['name']) ?></strong><small>PDF · <?= number_format($file['size']/1024) ?> KB · <?= e(thai_date($card['updated_at'])) ?></small></span><a class="button secondary" href="/files/<?= $file['id'] ?>?download=1">ดาวน์โหลด <?= icon('download',18) ?></a></div><?php endforeach; if(!$documentFiles): ?><p class="muted">ยังไม่มีไฟล์แนบ</p><?php endif ?></article><?php endif; endforeach ?></div><?php pagination($count,$page); endif ?></section>
